const map    = f => rf => (acc, x) => rf(acc, f(x));
const filter = p => rf => (acc, x) => (p(x) ? rf(acc, x) : acc);
const comp   = (...fs) => rf => fs.reduceRight((r, f) => f(r), rf);

const xf = comp(filter(isEven), map(square));        // reusable transformation value
const push = xf((acc, x) => (acc.push(x), acc));     // the 'job' is supplied here
const into = (src, acc = []) => { for (const x of src) acc = push(acc, x); return acc; };
into([1, 2, 3, 4]);                                  // array source
into(new Set([1, 2, 3]));                            // any iterable source
